contract InvMutTest {
    C c;
    bool rejectPayments;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool reject) public {
        rejectPayments = reject;

        uint etherBefore = address(c).balance;
        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint etherAfter = address(c).balance;
        uint recordedAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted == rejectPayments &&
               recordedAfter == recordedBefore &&
               etherAfter == etherBefore);
    }

    receive() external payable {
        if (rejectPayments) { revert(); }
    }
}

