pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;
    bool rejectPayments;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(bool reject) internal {
        rejectPayments = reject;
        uint etherBefore = address(c).balance;
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint etherAfter = address(c).balance;
        uint256 recordedAfter;
        try c.balances(address(this)) returns (uint256 __r) { recordedAfter = __r; } catch { return; }
        assertTrue(reverted == rejectPayments &&
               recordedAfter == recordedBefore &&
               etherAfter == etherBefore);
    }

    function testFuzz_run(bool reject) public {
        _run(reject);
    }

    receive() external payable {
        if (rejectPayments) { revert(); }
    }
}
